parameters.jsCode:
const inv = $('AI Reads Invoice').item.json.output;
const po = $('Find Purchase Order').item.json || {};
const gr = $('Find Delivery Record').item.json || {};

const invoiceTotal = Number(inv.totalAmount || 0);
const poAmount = Number(po.poAmount || 0);
const receivedAmount = Number(gr.receivedAmount || 0);

const claimType = String(inv.claimType || 'material_supply');
const isProgressClaim = claimType === 'progress_claim' || claimType === 'final_account' || claimType === 'variation';
const claimLabels = { progress_claim: 'Progress payment', material_supply: 'Materials', plant_hire: 'Equipment rental', variation: 'Change order', final_account: 'Final payment' };
const claimLabel = claimLabels[claimType] || claimType;

const claimedToDate = Number(inv.claimedToDate || 0);
const previouslyCertified = Number(inv.previouslyCertified || 0);
const thisClaim = Number(inv.thisClaim || 0);
const retentionPercent = Number(inv.retentionPercent || 0);
const retentionAmount = Number(inv.retentionAmount || 0);
const lienWaiver = inv.lienWaiverAttached === true;

const tolerance = 0.02; // amounts may differ by up to 2%
const flags = [];

// Is there a matching purchase order and job number?
if (!po.poNumber) { flags.push('Purchase order not found'); }
if (!inv.jobNumber) { flags.push('Job number missing'); }

// Materials and equipment: invoice must match the PO and the delivery record
if (!isProgressClaim && !gr.poNumber) { flags.push('No delivery record found'); }

const poVariance = poAmount > 0 ? Math.abs(invoiceTotal - poAmount) / poAmount : 1;
const grVariance = receivedAmount > 0 ? Math.abs(invoiceTotal - receivedAmount) / receivedAmount : 1;

if (!isProgressClaim && po.poNumber && poVariance > tolerance) { flags.push('Amount differs from PO by more than 2%'); }
if (!isProgressClaim && gr.poNumber && grVariance > tolerance) { flags.push('Amount differs from delivery record by more than 2%'); }

// Progress payments: the running totals must add up
if (isProgressClaim) {
  if (claimedToDate > 0 && poAmount > 0 && claimedToDate > poAmount * 1.001) {
    flags.push('Billed more than the contract value');
  }
  if (claimedToDate > 0 && previouslyCertified > 0) {
    const expectedThisClaim = claimedToDate - previouslyCertified;
    if (thisClaim > 0 && Math.abs(expectedThisClaim - thisClaim) > 1) {
      flags.push('Billing math does not add up');
    }
  }
  if (retentionPercent === 0 && retentionAmount === 0) {
    flags.push('No retention held back');
  }
  if (!lienWaiver) {
    flags.push('Lien waiver missing');
  }
}

// Checks for every invoice
if (po.vendorName && inv.vendorName && po.vendorName.toLowerCase() !== inv.vendorName.toLowerCase()) { flags.push('Vendor name does not match PO'); }
if (invoiceTotal > 50000) { flags.push('Large invoice (over 50k)'); }
if (po.status && po.status !== 'open') { flags.push('Contract is not open'); }

const netPayable = Math.round((invoiceTotal - retentionAmount) * 100) / 100;

return {
  json: {
    invoiceKey: $('Create Invoice ID').item.json.invoiceKey,
    messageId: $('Create Invoice ID').item.json.messageId,
    vendorName: inv.vendorName,
    invoiceNumber: inv.invoiceNumber,
    poNumber: inv.poNumber,
    jobNumber: inv.jobNumber || '',
    costCode: inv.costCode || '',
    claimType: claimType,
    claimLabel: claimLabel,
    isProgressClaim: isProgressClaim,
    invoiceDate: inv.invoiceDate,
    dueDate: inv.dueDate,
    currency: inv.currency,
    totalAmount: invoiceTotal,
    claimedToDate: claimedToDate,
    previouslyCertified: previouslyCertified,
    thisClaim: thisClaim,
    retentionPercent: retentionPercent,
    retentionAmount: retentionAmount,
    netPayable: netPayable,
    lienWaiverAttached: lienWaiver,
    poAmount: poAmount,
    receivedAmount: receivedAmount,
    poVariancePct: Math.round(poVariance * 10000) / 100,
    riskFlags: flags,
    riskCount: flags.length,
    routing: flags.length > 0 ? 'exception' : 'clean'
  }
};

