// Gmail names attachments attachment_0, attachment_1, ...
// Pick the first PDF, whatever position it's in (a logo image is often first).
const b = $input.item.binary || {};
const key = Object.keys(b).find(k => {
  const f = b[k] || {};
  return String(f.mimeType || '').toLowerCase().includes('pdf') || String(f.fileName || '').toLowerCase().endsWith('.pdf');
});
if (key) {
  return { json: $input.item.json, binary: { invoicePdf: b[key] } };
}
return { json: $input.item.json };

