// Airtable search returns { id, createdTime, fields: {...} }. Flatten it so
// later steps can read the record's fields directly by name.
return $input.all().map((it, i) => {
  const j = it.json || {};
  const flat = j.fields ? Object.assign({ id: j.id, createdTime: j.createdTime }, j.fields) : j;
  return { json: flat, pairedItem: { item: i } };
});

